python3 -c "import pandas as pd; df = pd.read_csv('data/restaurants/clean_restaurant_2022.csv'); 
cities = ['Minneapolis', 'Toledo', 'Cleveland', 'Columbus'];
cuisines = ['American', 'Mediterranean', 'Chinese', 'Italian'];
for city in cities:
    city_df = df[df['City'] == city]
    print(f'Restaurants in {city}:')
    for cuisine in cuisines:
        match = city_df[city_df['Cuisines'].str.contains(cuisine, case=False, na=False)]
        if not match.empty:
            print(f'  {cuisine}: {match[\"Name\"].tolist()[:2]}')
"

